    const auto functionId = statements.InsertFunctionName("vkCmdDrawIndirect");
    statements.InsertApiEvent(this->block_index_, functionId, call_info.thread_id);

    RecordField(
        statements, fieldInfo, 1, "commandBuffer", "VkCommandBuffer", commandBuffer);
    RecordField(
        statements, fieldInfo, 2, "buffer", "VkBuffer", buffer);
    RecordField(
        statements, fieldInfo, 3, "offset", "VkDeviceSize", offset);
    RecordField(
        statements, fieldInfo, 4, "drawCount", "uint32_t", drawCount);
    RecordField(
        statements, fieldInfo, 5, "stride", "uint32_t", stride);

