void VulkanSqliteConsumer::Process_vkCreateDisplayPlaneSurfaceKHR(
    const ApiCallInfo&                          call_info,
    VkResult                                    returnValue,
    format::HandleId                            instance,
    StructPointerDecoder<Decoded_VkDisplaySurfaceCreateInfoKHR>* pCreateInfo,
    StructPointerDecoder<Decoded_VkAllocationCallbacks>* pAllocator,
    HandlePointerDecoder<VkSurfaceKHR>*         pSurface)
{
    FieldInfo fieldInfo = {this->block_index_, 0, 0, 0};
    const auto functionId = statements.InsertFunctionName("vkCreateDisplayPlaneSurfaceKHR");
    statements.InsertApiEvent(this->block_index_, functionId, call_info.thread_id);

    RecordField(
        statements, fieldInfo, 1, "instance", "VkInstance", instance);
    FieldToSqlite(statements, fieldInfo, 2, "pCreateInfo", pCreateInfo, "const VkDisplaySurfaceCreateInfoKHR*");
    FieldToSqlite(statements, fieldInfo, 3, "pAllocator", pAllocator, "const VkAllocationCallbacks*");
    FieldToSqlite(statements, fieldInfo, 4, "pSurface", pSurface, "VkSurfaceKHR*");

    statements.InsertApiEventReturns(this->block_index_, "VkResult", returnValue);
    auto [surfaceValid, surface] = GetHandle(pSurface);
    if (!surfaceValid)
    {
        if (returnValue == VK_SUCCESS)
        {
            GFXRECON_SQLITE_LOG_WARNING("Failed to create surface, invalid pSurface handle");
        }
        return;
    }

    auto [createInfoValid, createInfo] = GetMetaStructPointer(pCreateInfo);
    if (!createInfoValid)
    {
        if (returnValue == VK_SUCCESS)
        {
            GFXRECON_SQLITE_LOG_WARNING("Failed to create surface, invalid pCreateInfo struct");
        }
        return;
    }

    LogUnsupportedPNext(createInfo->pNext);

    auto createInfoType = createInfo->decoded_value->sType;

    statements.InsertSurface(ToInt64(surface), createInfoType, this->block_index_);
}
